1	1	import io\nimport xml.etree.ElementTree as ET\nimport os\nimport sys\nfrom datetime import datetime\nfrom tkinter import Tk, filedialog\nfrom dateutil.relativedelta import relativedelta\nfrom decimal import Decimal\nimport zipfile\nfrom io import BytesIO, StringIO\n\n    # Get last month name\nnow = datetime.now()\none_month_ago = now - relativedelta(months=1)\nmonth_name = one_month_ago.strftime("%B")\n\ndef format_date(date_str, original_format='%d.%m.%Y'):\n    if date_str:\n        try:\n            date_obj = datetime.strptime(date_str, original_format)\n            return date_obj.strftime('%Y-%m-%d')\n        except ValueError as e:\n            print(f"Error formatting date: {date_str}, error: {e}")\n            return None  \n    return None\n\ndef process_xml(xml_data, schema_path):\n    ns = {\n        'inv': 'http://www.stormware.cz/schema/version_2/invoice.xsd',\n        'typ': 'http://www.stormware.cz/schema/version_2/type.xsd',\n        # Add other namespaces as needed\n    }\n\n    root = ET.parse(StringIO(xml_data)).getroot()\n    limit = 400\n    count = 0\n\n\n    created_files = []  # List to store paths of created files\n\n    # Iterate over each 'doklad' in the user-selected XML\n    for idx, doklad in enumerate(root.iter('doklad'), start=1):\n        if count < limit:\n            kniha = doklad.find('kniha')\n            var_symbol = doklad.find('var_symbol')\n            ext_cislo = doklad.find('ext_cislo')\n            dat_vyst = doklad.find('dat_vyst')\n            dat_zd_pln = doklad.find('dat_zd_pln')\n            dat_spl = doklad.find('dat_spl')\n            nazev = doklad.find('nazev')\n            obec = doklad.find('obec')\n            ulice = doklad.find('ulice')\n            psc = doklad.find('psc')\n            forma_uhrady = doklad.find('forma_uhrady')\n            forma = forma_uhrady.text\n            if forma == 'DO':\n                forma = 'Dobierkou'\n            elif forma == 'PKO':\n                forma = 'Plat.kartou'\n            \n            polozky = doklad.find('polozky')\n            polozka = polozky.find('polozka')\n            polozka_cena_cenik = polozka.find('cena_cenik')\n            polozka_cena_celkem = polozka.find('cena_celkem')\n            polozka_casta_dph = polozka.find('castka_dph')\n\n            polozka_length = len(polozky.findall('polozka'))\n\n            polozka_elements = polozky.findall('polozka')\n\n            cena_celkem = None\n            cena_cenik = None\n            castka_dph = None\n            sumar = None\n\n            polozka_cena_cenik2 = None\n            polozka_cena_celkem2 = None\n            polozka_casta_dph2 = None\n            sumar2 = None\n\n            cena_zaok = None\n            cena_zaok_celkem = None\n            cena_zaok_dph = None\n            zaokSumar = None\n\n            total_sum_str = None\n            if polozka_length == 1:\n                cena_cenik = polozka_cena_cenik.text\n                cena_celkem = polozka_cena_celkem.text\n                castka_dph = polozka_casta_dph.text\n                total_sum_str = str(Decimal(cena_celkem) + Decimal(castka_dph))\n                sumar = total_sum_str\n\n            if polozka_length == 2:\n                cena_cenik = polozka_cena_cenik.text\n                cena_celkem = polozka_cena_celkem.text\n                castka_dph = polozka_casta_dph.text\n                total_sum_str = str(Decimal(cena_celkem) + Decimal(castka_dph))\n                sumar = total_sum_str\n\n                polozka2 = polozka_elements[1]\n                polozka_cena_cenik2 = polozka2.find('cena_cenik').text\n                polozka_cena_celkem2 = polozka2.find('cena_celkem').text\n                polozka_casta_dph2 = polozka2.find('castka_dph').text\n                total_sum_str2 = str(Decimal(polozka_cena_celkem2) + Decimal(polozka_casta_dph2))\n                sumar2 = total_sum_str2\n\n            if polozka_length == 3:\n                polozka1 = polozka_elements[0]\n                cena_zaok = polozka1.find('cena_cenik').text\n                cena_zaok_celkem = polozka1.find('cena_celkem').text\n                cena_zaok_dph = polozka1.find('castka_dph').text\n                total_sum_str1 = str(Decimal(cena_zaok_celkem) + Decimal(cena_zaok_dph))\n                zaokSumar = total_sum_str1\n\n                polozka2 = polozka_elements[1]\n                cena_cenik = polozka2.find('cena_cenik').text\n                cena_celkem = polozka2.find('cena_celkem').text\n                polozka_casta_dph = polozka2.find('castka_dph').text\n                total_sum_str = str(Decimal(cena_celkem) + Decimal(polozka_casta_dph))\n                sumar = total_sum_str\n\n                polozka3 = polozka_elements[2]\n                polozka_cena_cenik2 = polozka3.find('cena_cenik').text\n                polozka_cena_celkem2 = polozka3.find('cena_celkem').text\n                polozka_casta_dph2 = polozka3.find('castka_dph').text\n                total_sum_str2 = str(Decimal(polozka_cena_celkem2) + Decimal(polozka_casta_dph2))\n                sumar2 = total_sum_str2\n\n\n            dat_vyst_text = dat_vyst.text if dat_vyst is not None else None\n            dat_zd_pln_text = dat_zd_pln.text if dat_zd_pln is not None else None\n            dat_spl_text = dat_spl.text if dat_spl is not None else None\n\n            formatted_dat_vyst = format_date(dat_vyst_text)\n            formatted_dat_zd_pln = format_date(dat_zd_pln_text)\n            formatted_dat_spl = format_date(dat_spl_text)\n\n            if kniha is not None and var_symbol is not None and ext_cislo is not None and dat_vyst is not None and dat_zd_pln is not None and dat_spl is not None:\n                schema_tree = ET.parse(schema_path)\n                schema_root = schema_tree.getroot()\n\n                number_requested = schema_root.find('.//typ:numberRequested', ns)\n                symVar = schema_root.find('.//inv:symVar', ns)\n                symPar = schema_root.find('